// setup.mjs — creates/overwrites all the project files in one go.
// Run with:  node setup.mjs   (from inside the latest/ folder)
import fs from "fs";
import path from "path";

const files = {
  "index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta name=\"theme-color\" content=\"#0756a5\" />\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.svg\" />\n    <title>BlueBank Demo NetBanking</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.jsx\"></script>\n  </body>\n</html>",
  "src/main.jsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App.jsx\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);",
  "src/App.jsx": "// React hook for managing component state.\nimport { useState, useEffect } from \"react\";\nimport AccountStatement from \"./pages/AccountStatement\";\n\n// Pages and layout shown after login.\nimport Navbar from \"./components/banking/Navbar\";\nimport Home from \"./pages/Home\";\nimport Accounts from \"./pages/Accounts\";\n\n// Icons used on the login page.\nimport { ShieldCheck, Eye, EyeOff } from \"lucide-react\";\n\n// Address-bar path for each page (only the part after localhost:xxxx changes).\nconst PAGE_PATHS = {\n  home: \"/retail-app/dashboard\",\n  accounts: \"/retail-app/my-accounts\",\n  statement: \"/retail-app/my-accounts/download-statement\",\n};\n\n// Find which page belongs to a path. Unknown path (like \"/\") falls back to home.\nfunction pageFromPath(pathname) {\n  const hit = Object.entries(PAGE_PATHS).find(([, path]) => path === pathname);\n  return hit ? hit[0] : \"home\";\n}\n\nfunction Auth({ onSuccess }) {\n  const [mode, setMode] = useState(\"login\");\n  const [bankingType, setBankingType] = useState(\"personal\");\n  const [customerId, setCustomerId] = useState(\"\");\n  const [name, setName] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [showPassword, setShowPassword] = useState(false);\n\n  function handleSubmit(event) {\n    event.preventDefault();\n\n    if (!customerId.trim() || !password.trim()) {\n      alert(\"Please enter your demo credentials.\");\n      return;\n    }\n\n    if (mode === \"register\" && !name.trim()) {\n      alert(\"Please enter your name.\");\n      return;\n    }\n\n    // Create a temporary demo session without real banking authentication.\n    onSuccess({\n      name: mode === \"register\" ? name.trim() : customerId.trim(),\n      email: `${customerId.trim()}@demo.local`,\n    });\n  }\n\n  return (\n    <div className=\"bank-login-page\">\n\n      {/* LEFT PROMOTIONAL PANEL */}\n      <section className=\"login-promo-panel\">\n        <img src=\"https://now.hdfc.bank.in/content/dam/hdfc-bank-cms/assets/corebanking/nb/en/v1/images/login-assets/login.svg\" alt=\"\" />\n      </section>\n\n      {/* RIGHT LOGIN PANEL */}\n      <section className=\"login-form-panel\">\n\n        <div className=\"login-form-container\">\n\n          <div className=\"login-brand\">\n            <img src=\"https://now.hdfc.bank.in/auth/resources/7ih90/login/hdfc-retail-web/assets/hdfc-bank-logo.svg\" alt=\"\" />\n          </div>\n\n          <h2 className=\"login-welcome\">\n            Welcome to NetBanking\n          </h2>\n\n          <div className=\"banking-tabs\">\n            <button\n              className={bankingType === \"personal\" ? \"banking-tab active\" : \"banking-tab\"}\n              onClick={() => setBankingType(\"personal\")}\n            >\n              Personal Banking\n            </button>\n\n            <button\n              className={bankingType === \"cards\" ? \"banking-tab active\" : \"banking-tab\"}\n              onClick={() => setBankingType(\"cards\")}\n            >\n              Credit Cards Only\n            </button>\n          </div>\n\n          {/* QR LOGIN CARD */}\n          <div className=\"qr-login-card\">\n\n            <div className=\"qr-placeholder\">\n             \n               <img width=\"72\" height=\"72\" aria-hidden=\"true\" id=\"qr-scan-mb\" className=\"adobe-asset\" alt=\"Scan QR code\" data-filename=\"QR_Scan.gif\" src=\"https://now.hdfc.bank.in/content/dam/hdfc-bank-cms/assets/corebanking/nb/en/v1//images/kavach-assets/QR_Scan.gif\" role=\"presentation\" loading=\"lazy\" />\n              <small>DEMO QR</small>\n            </div>\n\n            <div className=\"qr-information\">\n              <h3>\n                Login without Password\n                <span className=\"new-tag\">NEW</span>\n              </h3>\n\n              <p>\n                Experience secure demo login with our\n                simulated QR authentication.\n              </p>\n            </div>\n\n            <span className=\"qr-arrow\">\u2192</span>\n          </div>\n\n          <div className=\"qr-message\">\n            This is a visual QR demo. No real bank login is connected.\n          </div>\n\n          <div className=\"or-divider\">\n            <span></span>\n            <p>Or</p>\n            <span></span>\n          </div>\n\n          {/* LOGIN FORM */}\n          <form onSubmit={handleSubmit} className=\"bank-login-form\">\n\n            {mode === \"register\" && (\n              <div className=\"bank-field\">\n                <label>Full Name</label>\n                <input\n                  type=\"text\"\n                  placeholder=\"Enter your full name\"\n                  value={name}\n                  onChange={(e) => setName(e.target.value)}\n                  required\n                />\n              </div>\n            )}\n\n            <div className=\"bank-field\">\n              <label>\n                {bankingType === \"personal\"\n                  ? \"Customer ID / User ID\"\n                  : \"Demo Card User ID\"}\n              </label>\n\n              <input\n                type=\"text\"\n                placeholder=\"Enter your demo ID\"\n                value={customerId}\n                onChange={(e) => setCustomerId(e.target.value)}\n                required\n              />\n\n              {mode === \"login\" && (\n                <a href=\"#demo-help\" className=\"bank-help-link\">\n                  Forgot Demo ID?\n                </a>\n              )}\n            </div>\n\n            <div className=\"bank-field\">\n              <label>Password</label>\n\n              <div className=\"bank-password-field\">\n                <input\n                  type={showPassword ? \"text\" : \"password\"}\n                  placeholder=\"Enter demo password\"\n                  value={password}\n                  onChange={(e) => setPassword(e.target.value)}\n                  required\n                />\n\n                <button\n                  type=\"button\"\n                  onClick={() => setShowPassword(!showPassword)}\n                >\n                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}\n                </button>\n              </div>\n            </div>\n\n            <button type=\"submit\" className=\"bank-submit-button\">\n              {mode === \"register\" ? \"Register Now\" : \"Login\"}\n            </button>\n\n          </form>\n\n          <div className=\"bank-register-link\">\n            {mode === \"login\" ? (\n              <>\n                Not registered for Demo NetBanking?\n                <button onClick={() => setMode(\"register\")}>\n                  Register Now\n                </button>\n              </>\n            ) : (\n              <>\n                Already registered?\n                <button onClick={() => setMode(\"login\")}>\n                  Login\n                </button>\n              </>\n            )}\n          </div>\n\n          <div className=\"login-security-note\">\n            <ShieldCheck size={15} />\n            Educational demo only. Not an official bank website.\n          </div>\n\n        </div>\n      </section>\n\n    </div>\n  );\n}\n\nexport default function App() {\n  const [user, setUser] = useState(null);\n  const [page, setPageState] = useState(() => pageFromPath(window.location.pathname));\n\n  // Change the page AND the address-bar path together (so Back button works too).\n  function setPage(next) {\n    setPageState(next);\n    window.history.pushState({}, \"\", PAGE_PATHS[next]);\n  }\n\n  // Browser Back / Forward buttons: show the page that matches the path.\n  useEffect(() => {\n    const onPop = () => setPageState(pageFromPath(window.location.pathname));\n    window.addEventListener(\"popstate\", onPop);\n    return () => window.removeEventListener(\"popstate\", onPop);\n  }, []);\n\n  function login(newUser) {\n    setUser(newUser);\n    window.history.replaceState({}, \"\", PAGE_PATHS[page]);\n  }\n\n  function logout() {\n    setUser(null);\n    setPageState(\"home\");\n    window.history.pushState({}, \"\", \"/\");\n  }\n\n  if (!user) {\n    return <Auth onSuccess={login} />;\n  }\n\n  return (\n    <div className=\"min-h-screen bg-slate-50\">\n      <Navbar page={page} setPage={setPage} user={user} onLogout={logout} />\n\n      {page === \"home\" && <Home user={user} setPage={setPage} />}\n      {page === \"accounts\" && <Accounts setPage={setPage} />}\n      {page === \"statement\" && <AccountStatement setPage={setPage} />}\n\n      <footer className=\"border-t border-slate-200 px-6 py-5 text-center text-xs text-slate-400\">\n        Educational demo only \u2022 Fictional data \u2022 Not an official bank website\n      </footer>\n    </div>\n  );\n}\n",
  "src/data/demoAccount.js": "// Shared fictional account info + formatting helpers used by all banking pages.\n// Everything here is DEMO data. Change it in one place and every page updates.\n\n// Same logo URL as the login page.\nexport const LOGO_URL =\n  \"https://now.hdfc.bank.in/auth/resources/7ih90/login/hdfc-retail-web/assets/hdfc-bank-logo.svg\";\n\nexport const ACCOUNT = {\n  type: \"Savings A/C\",\n  masked: \"**** **** **00 01\", // fictional\n  openingBalance: 45000, // fictional\n};\n\nexport const formatAmount = (amount) =>\n  new Intl.NumberFormat(\"en-IN\", {\n    style: \"currency\",\n    currency: \"INR\",\n    maximumFractionDigits: 2,\n  }).format(amount);\n\nexport const formatDate = (date) =>\n  date.toLocaleDateString(\"en-IN\", { day: \"2-digit\", month: \"short\", year: \"numeric\" });\n\n// dd-mm-yyyy, the format shown in the statement date boxes.\nexport const formatDMY = (date) =>\n  `${String(date.getDate()).padStart(2, \"0\")}-${String(date.getMonth() + 1).padStart(2, \"0\")}-${date.getFullYear()}`;\n",
  "src/data/demoTransactions.js": "// Fictional transaction generator for the demo app.\n// - Every month is generated from a fixed seed, so the same month always gives the same data.\n// - Transactions in the future (after today) are hidden, so data always follows the current date.\n// - Running balance is continuous from ORIGIN: closing balance of one month = opening of the next.\n// All names, numbers and amounts are made up. This is NOT a real bank record.\n\n// First month that has data, and the fictional balance before it starts.\nconst ORIGIN = { year: 2025, month: 4 };\nconst OPENING_AT_ORIGIN = 70000;\n\n// Fictional people / shops used in narrations.\nconst PEOPLE = [\n  \"AARAV MEHTA\", \"DIYA PATEL\", \"KABIR SINGH\", \"MEERA NAIR\", \"ROHAN DESAI\", \"ISHA VERMA\",\n  \"NIKHIL RAO\", \"ANANYA GUPTA\", \"VIKRAM JOSHI\", \"SANYA KAPOOR\", \"ARJUN MALIK\", \"TARA IYER\",\n];\nconst SHOPS = [\n  { name: \"FRESHMART GROCERY\", category: \"Shopping\" },\n  { name: \"QUICKBITES CAFE\", category: \"Food\" },\n  { name: \"METRO RIDES\", category: \"Travel\" },\n  { name: \"BOOKNEST STORE\", category: \"Shopping\" },\n  { name: \"SPICE GARDEN\", category: \"Food\" },\n  { name: \"PHARMACARE\", category: \"Health\" },\n];\nconst CITIES = [\"INDORE\", \"BHOPAL\", \"PUNE\", \"DELHI\"];\nconst MON = [\"JAN\",\"FEB\",\"MAR\",\"APR\",\"MAY\",\"JUN\",\"JUL\",\"AUG\",\"SEP\",\"OCT\",\"NOV\",\"DEC\"];\n\n// Small seeded random generator (same seed -> same numbers).\nfunction makeRng(seed) {\n  let a = seed;\n  return () => {\n    a |= 0; a = (a + 0x6d2b79f5) | 0;\n    let t = Math.imul(a ^ (a >>> 15), 1 | a);\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\nconst pad = (n, size = 2) => String(n).padStart(size, \"0\");\nconst round2 = (n) => Math.round(n * 100) / 100;\n\n// Build ALL transactions of one month (no future filtering here).\nfunction buildMonth(month, year) {\n  const rand = makeRng(year * 100 + month);\n  const int = (a, b) => a + Math.floor(rand() * (b - a + 1));\n  const pick = (arr) => arr[Math.floor(rand() * arr.length)];\n  const ref12 = () => String(int(100000000000, 999999999999));\n  const dim = new Date(year, month, 0).getDate();\n  const list = [];\n  let n = 0;\n\n  const add = (day, type, amount, description, narration, category, reference) => {\n    list.push({\n      id: `TXN-${year}${pad(month)}-${pad(++n, 3)}`,\n      date: new Date(year, month - 1, day),\n      description, // short text for tables / PDF\n      narration, // long bank-style text for Excel / CSV\n      category,\n      type,\n      amount: round2(amount),\n      reference,\n    });\n  };\n\n  // Fixed monthly items\n  add(3, \"Debit\", 18250, \"ACH D - SUNRISE HOUSING FIN\", `ACH D- SUNRISE HOUSING FINANCE-LN70356${pad(month)}EMI`, \"EMI\", `00000${ref12()}`);\n  add(5, \"Debit\", 30000, \"NEFT DR - SELF RD\", \"NEFT DR-DEMO0000321-SELF-RD INSTALMENT\", \"Transfer\", `DEMOH${int(10000000, 99999999)}`);\n  add(int(8, 14), \"Debit\", int(900, 2400) + int(0, 99) / 100, \"IB BILLPAY DR - ELECTRICITY\", \"IB BILLPAY DR-DEMOPAY-ELECTRICITY BOARD-XXXXXX2001\", \"Bills\", `17${ref12()}`);\n  add(int(15, 20), \"Debit\", pick([299, 399, 599]), \"IB BILLPAY DR - MOBILE\", \"IB BILLPAY DR-DEMOPAY-MOBILE RECHARGE-XXXXXX2001\", \"Bills\", `17${ref12()}`);\n\n  // Quarterly interest on 1st of Jan / Apr / Jul / Oct\n  if ([1, 4, 7, 10].includes(month)) {\n    const prevEnd = new Date(year, month - 1, 0);\n    add(1, \"Credit\", int(40, 140) + int(0, 99) / 100, \"INTEREST PAID\", `INTEREST PAID TILL ${pad(prevEnd.getDate())}-${pad(prevEnd.getMonth() + 1)}-${prevEnd.getFullYear()}`, \"Interest\", \"000000000000000\");\n  }\n\n  // UPI payments out (shops and people)\n  const upiOut = int(6, 9);\n  for (let i = 0; i < upiOut; i++) {\n    const amount = pick([40, 60, 85, 120, 150, 199, 250, 320, 450, 600, 899, 1200, 1500]);\n    const ref = ref12();\n    if (rand() < 0.5) {\n      const shop = pick(SHOPS);\n      add(int(1, dim), \"Debit\", amount, `UPI - ${shop.name}`, `UPI-${shop.name}-SHOP${int(100, 999)}@demo-${ref}-PAYMENT FROM PHONE`, shop.category, `0000${ref}`);\n    } else {\n      const name = pick(PEOPLE);\n      add(int(1, dim), \"Debit\", amount, `UPI - ${name}`, `UPI-${name}-${name.split(\" \")[0].toLowerCase()}@demo-${ref}-PAYMENT FROM PHONE`, \"Transfer\", `0000${ref}`);\n    }\n  }\n\n  // UPI money received\n  const upiIn = int(1, 3);\n  for (let i = 0; i < upiIn; i++) {\n    const name = pick(PEOPLE);\n    const ref = ref12();\n    add(int(1, dim), \"Credit\", pick([500, 1000, 1500, 2000, 3500, 5000]), `UPI - ${name}`, `UPI-${name}-${name.split(\" \")[0].toLowerCase()}@demo-${ref}-PAYMENT FROM PHONE`, \"Transfer\", `0000${ref}`);\n  }\n\n  // ATM cash withdrawals (0 to 2 per month)\n  const atm = int(0, 2);\n  for (let i = 0; i < atm; i++) {\n    add(int(1, dim), \"Debit\", pick([2000, 3000, 5000]), `ATM WDL - ${pick(CITIES)}`, `ATW-4000XXXXXX0000-DEMOATM01-${pick(CITIES)}`, \"Cash\", `00000000${int(10000000, 99999999)}`);\n  }\n\n  // Salary on the last day of the month\n  const code = `${MON[month - 1]}${String(year).slice(2)}SALARY`;\n  add(dim, \"Credit\", 64000 + (month % 4) * 1500, \"SALARY - NORTHWIND SYSTEMS\", `SALARY - NORTHWIND SYSTEMS PVT LTD-${code}`, \"Income\", code);\n\n  // Keep order by date (sort is stable, so same-day items keep their order)\n  return list.sort((a, b) => a.date - b.date);\n}\n\n// Public: transactions of a month, only up to TODAY (future days are hidden).\nexport function getMonthlyTransactions(month, year) {\n  // No data before the origin month.\n  if (year * 12 + month < ORIGIN.year * 12 + ORIGIN.month) return [];\n\n  const now = new Date();\n  const endOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59);\n  return buildMonth(month, year).filter((t) => t.date <= endOfToday);\n}\n\nexport function calculateMonthlySummary(transactions) {\n  const credit = transactions\n    .filter((item) => item.type === \"Credit\")\n    .reduce((total, item) => total + item.amount, 0);\n\n  const debit = transactions\n    .filter((item) => item.type === \"Debit\")\n    .reduce((total, item) => total + item.amount, 0);\n\n  return { credit: round2(credit), debit: round2(debit) };\n}\n\n// Balance at the START of the given date (all transactions before it are included).\nexport function getBalanceBefore(date) {\n  let balance = OPENING_AT_ORIGIN;\n  const cursor = new Date(ORIGIN.year, ORIGIN.month - 1, 1);\n  while (cursor <= date) {\n    for (const t of getMonthlyTransactions(cursor.getMonth() + 1, cursor.getFullYear())) {\n      if (t.date < date) balance += t.type === \"Credit\" ? t.amount : -t.amount;\n    }\n    cursor.setMonth(cursor.getMonth() + 1);\n  }\n  return round2(balance);\n}\n\n// Balance right now (includes everything up to end of today).\nexport function getCurrentBalance() {\n  const now = new Date();\n  return getBalanceBefore(new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1));\n}\n",
  "src/components/banking/Navbar.jsx": "// Top navigation: logo, search, support icons, avatar and the main menu tabs.\nimport { Search, Bell, Power, Menu, CircleHelp } from \"lucide-react\";\nimport { LOGO_URL } from \"../../data/demoAccount\";\n\n// All tabs are shown for the look; only the ones with `page` actually navigate.\nconst tabs = [\n  { label: \"Home\", page: \"home\" },\n  { label: \"Accounts\", page: \"accounts\" },\n  { label: \"Send Money\" },\n  { label: \"Cards\" },\n  { label: \"FD/RD\" },\n  { label: \"Bills & Recharges\" },\n  { label: \"Loans\" },\n  { label: \"Invest\" },\n  { label: \"Insure\" },\n];\n\nexport default function Navbar({ page, setPage, user, onLogout }) {\n  // The statement page belongs to the Accounts tab.\n  const activePage = page === \"statement\" ? \"accounts\" : page;\n  const initials = (user.name || \"U\").slice(0, 2).toUpperCase();\n\n  return (\n    <header className=\"bg-[#08295c] text-white\">\n      {/* Row 1: logo, search, icons */}\n      <div className=\"mx-auto flex max-w-7xl items-center justify-between gap-4 px-4 py-4 sm:px-8\">\n        <div className=\"flex items-center gap-2\">\n          <img src={LOGO_URL} alt=\"Bank logo\" className=\"h-8 w-auto rounded-sm bg-white p-0.5\" />\n          <span className=\"rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-bold text-amber-700\">DEMO</span>\n        </div>\n\n        <div className=\"hidden flex-1 justify-center md:flex\">\n          <div className=\"flex w-full max-w-md items-center gap-3 rounded-lg bg-white px-4 py-2.5 text-slate-500\">\n            <Search size={18} />\n            <input\n              type=\"text\"\n              placeholder=\"Book Deposit / Download Form 16 / etc.\"\n              className=\"w-full bg-transparent text-sm outline-none\"\n            />\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-4 text-white/80\">\n          <span className=\"hidden items-center gap-2 text-sm lg:flex\">\n            <CircleHelp size={18} /> Services &amp; Support\n          </span>\n          <Bell size={19} />\n          <button type=\"button\" onClick={onLogout} aria-label=\"Logout\" title=\"Logout\">\n            <Power size={19} />\n          </button>\n          <div className=\"flex items-center gap-2 rounded-full bg-white/10 p-1 pl-3\">\n            <Menu size={17} />\n            <div className=\"grid h-8 w-8 place-items-center rounded-full bg-white text-xs font-bold text-[#08295c]\">\n              {initials}\n            </div>\n          </div>\n        </div>\n      </div>\n\n      {/* Row 2: menu tabs (scrolls sideways on small screens) */}\n      <nav className=\"mx-auto max-w-7xl overflow-x-auto px-4 sm:px-8\">\n        <ul className=\"flex min-w-max gap-8 text-sm\">\n          {tabs.map((tab) => {\n            const active = tab.page && tab.page === activePage;\n            return (\n              <li key={tab.label}>\n                <button\n                  type=\"button\"\n                  onClick={() => tab.page && setPage(tab.page)}\n                  className={`border-b-2 pb-3 pt-1 font-medium ${\n                    active ? \"border-white text-white\" : \"border-transparent text-white/70\"\n                  } ${tab.page ? \"cursor-pointer\" : \"cursor-default\"}`}\n                >\n                  {tab.label}\n                </button>\n              </li>\n            );\n          })}\n        </ul>\n      </nav>\n    </header>\n  );\n}\n",
  "src/components/banking/PageHero.jsx": "// Dark blue band under the navbar with an optional Back link and a page title.\n// Page cards use a negative top margin to overlap this band, like the real layout.\nimport { ArrowLeft } from \"lucide-react\";\n\nexport default function PageHero({ title, onBack, children }) {\n  return (\n    <div className=\"bg-gradient-to-b from-[#08295c] to-[#051b42] pb-28\">\n      <div className=\"mx-auto max-w-7xl px-4 pt-3 sm:px-8\">\n        {onBack && (\n          <button type=\"button\" onClick={onBack} className=\"flex items-center gap-2 text-sm text-white/80\">\n            <ArrowLeft size={16} /> Back\n          </button>\n        )}\n        <h1 className=\"mt-4 text-3xl font-semibold text-white\">{title}</h1>\n        {children}\n      </div>\n    </div>\n  );\n}\n",
  "src/components/banking/QuickLinks.jsx": "// \"Quick Links\" card shown on the right side of Accounts and Statement pages.\nimport { ChevronRight } from \"lucide-react\";\n\n// links = [{ label, icon: LucideIcon, onClick }]\nexport default function QuickLinks({ title = \"Quick Links\", links }) {\n  return (\n    <aside className=\"overflow-hidden rounded-2xl bg-white shadow-lg\">\n      <h2 className=\"bg-slate-100 px-6 py-5 text-lg font-semibold text-slate-800\">{title}</h2>\n      <ul className=\"p-3\">\n        {links.map(({ label, icon: Icon, onClick }) => (\n          <li key={label}>\n            <button\n              type=\"button\"\n              onClick={onClick}\n              className=\"flex w-full items-center justify-between rounded-lg px-3 py-3 text-left text-sm text-slate-700 hover:bg-slate-50\"\n            >\n              <span className=\"flex items-center gap-3\">\n                {Icon && <Icon size={18} className=\"text-blue-700\" />}\n                {label}\n              </span>\n              <ChevronRight size={16} className=\"text-blue-700\" />\n            </button>\n          </li>\n        ))}\n      </ul>\n    </aside>\n  );\n}\n",
  "src/components/banking/SendMoney.jsx": "// Send Money card: To / From account pickers + amount, with an Add Payee action.\n// Entirely a visual demo \u2014 nothing is actually transferred.\nimport { useState } from \"react\";\nimport { UserPlus, ArrowRight } from \"lucide-react\";\nimport { ACCOUNT } from \"../../data/demoAccount\";\n\nconst PAYEES = [\"Select a payee\", \"Rohan Desai - XXXX1234\", \"Priya Nair - XXXX5678\", \"Add a new payee...\"];\n\nexport default function SendMoney() {\n  const [mode, setMode] = useState(\"domestic\");\n  const [to, setTo] = useState(PAYEES[0]);\n  const [amount, setAmount] = useState(\"\");\n\n  function proceed() {\n    if (to === PAYEES[0] || !amount) {\n      alert(\"Please select a payee and enter an amount.\");\n      return;\n    }\n    alert(\"This is a demo. No real money transfer happens here.\");\n  }\n\n  return (\n    <div className=\"rounded-2xl bg-white p-6 shadow-lg\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <h2 className=\"font-semibold text-slate-800\">Send Money</h2>\n        <div className=\"flex items-center gap-3\">\n          <select\n            value={mode}\n            onChange={(e) => setMode(e.target.value)}\n            className=\"rounded-lg border border-slate-300 px-3 py-2 text-sm\"\n          >\n            <option value=\"domestic\">Domestic</option>\n            <option value=\"own\">Own Accounts</option>\n          </select>\n          <button type=\"button\" onClick={() => alert(\"Add Payee is not available in this demo.\")} className=\"flex items-center gap-1 text-sm font-semibold text-blue-800\">\n            <UserPlus size={16} /> Add Payee\n          </button>\n        </div>\n      </div>\n\n      <div className=\"mt-4 grid gap-4 sm:grid-cols-3\">\n        <div>\n          <label className=\"mb-1 block text-xs font-semibold text-slate-500\">To</label>\n          <select value={to} onChange={(e) => setTo(e.target.value)} className=\"w-full rounded-lg border border-slate-300 p-3 text-sm\">\n            {PAYEES.map((p) => <option key={p}>{p}</option>)}\n          </select>\n        </div>\n        <div>\n          <label className=\"mb-1 block text-xs font-semibold text-slate-500\">From</label>\n          <div className=\"w-full rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm text-slate-600\">\n            {ACCOUNT.type} \u00b7 {ACCOUNT.masked}\n          </div>\n        </div>\n        <div>\n          <label className=\"mb-1 block text-xs font-semibold text-slate-500\">Amount</label>\n          <div className=\"flex items-center rounded-lg border border-slate-300 p-3 text-sm\">\n            <span className=\"mr-1 text-slate-400\">\u20b9</span>\n            <input\n              type=\"number\"\n              min=\"0\"\n              value={amount}\n              onChange={(e) => setAmount(e.target.value)}\n              placeholder=\"0.00\"\n              className=\"w-full outline-none\"\n            />\n          </div>\n        </div>\n      </div>\n\n      <button type=\"button\" onClick={proceed} className=\"mt-5 flex items-center gap-2 rounded-lg bg-blue-800 px-6 py-2.5 text-sm font-semibold text-white hover:bg-blue-900\">\n        Proceed <ArrowRight size={16} />\n      </button>\n    </div>\n  );\n}\n",
  "src/components/banking/QuickRecharge.jsx": "// Quick Recharge card: Mobile / FASTag / DTH tabs with a number field and Proceed.\n// Visual demo only \u2014 no real recharge is performed.\nimport { useState } from \"react\";\nimport { Smartphone, Car, Tv } from \"lucide-react\";\n\nconst TABS = [\n  { id: \"mobile\", label: \"Mobile\", icon: Smartphone, placeholder: \"Enter Mobile Number\" },\n  { id: \"fastag\", label: \"FASTag\", icon: Car, placeholder: \"Enter Vehicle Number\" },\n  { id: \"dth\", label: \"DTH\", icon: Tv, placeholder: \"Enter Customer ID\" },\n];\n\nexport default function QuickRecharge() {\n  const [tab, setTab] = useState(\"mobile\");\n  const [value, setValue] = useState(\"\");\n  const active = TABS.find((t) => t.id === tab);\n\n  function proceed() {\n    if (!value.trim()) {\n      alert(`Please enter a value for ${active.label} recharge.`);\n      return;\n    }\n    alert(\"This is a demo. No real recharge happens here.\");\n  }\n\n  return (\n    <div className=\"rounded-2xl bg-white p-6 shadow-lg\">\n      <h2 className=\"font-semibold text-slate-800\">Quick Recharge</h2>\n\n      <div className=\"mt-4 flex gap-2 rounded-xl bg-slate-100 p-1\">\n        {TABS.map((t) => {\n          const Icon = t.icon;\n          const isActive = t.id === tab;\n          return (\n            <button\n              key={t.id}\n              type=\"button\"\n              onClick={() => { setTab(t.id); setValue(\"\"); }}\n              className={`flex flex-1 flex-col items-center gap-1 rounded-lg py-3 text-xs font-semibold ${\n                isActive ? \"bg-white text-blue-800 shadow\" : \"text-slate-500\"\n              }`}\n            >\n              <Icon size={18} />\n              {t.label}\n            </button>\n          );\n        })}\n      </div>\n\n      <div className=\"mt-4\">\n        <label className=\"mb-1 block text-xs font-semibold text-slate-500\">{active.placeholder}</label>\n        <input\n          type=\"text\"\n          value={value}\n          onChange={(e) => setValue(e.target.value)}\n          placeholder={active.placeholder}\n          className=\"w-full rounded-lg border border-slate-300 p-3 text-sm outline-none\"\n        />\n      </div>\n\n      <button type=\"button\" onClick={proceed} className=\"mt-4 w-full rounded-lg bg-blue-800 py-3 text-sm font-semibold text-white hover:bg-blue-900\">\n        Proceed\n      </button>\n    </div>\n  );\n}\n",
  "src/components/banking/BillsRecharges.jsx": "// \"Bills & Recharges\" strip: a row of category icons. Visual demo only.\nimport { Zap, Smartphone, Tv, Wifi, Flame, ShieldCheck } from \"lucide-react\";\n\nconst CATEGORIES = [\n  { label: \"Electricity\", icon: Zap },\n  { label: \"Mobile\", icon: Smartphone },\n  { label: \"DTH\", icon: Tv },\n  { label: \"Broadband\", icon: Wifi },\n  { label: \"Gas\", icon: Flame },\n  { label: \"Insurance\", icon: ShieldCheck },\n];\n\nexport default function BillsRecharges() {\n  return (\n    <div className=\"rounded-2xl bg-gradient-to-br from-blue-800 to-indigo-900 p-6 shadow-lg\">\n      <div className=\"flex items-center justify-between\">\n        <h2 className=\"font-semibold text-white\">Bills &amp; Recharges</h2>\n        <button type=\"button\" onClick={() => alert(\"This is not available in this demo.\")} className=\"text-sm font-semibold text-white/80\">\n          View All\n        </button>\n      </div>\n\n      <div className=\"mt-5 flex flex-wrap gap-5\">\n        {CATEGORIES.map((item) => {\n          const Icon = item.icon;\n          return (\n            <button\n              key={item.label}\n              type=\"button\"\n              onClick={() => alert(`${item.label} bill pay is not available in this demo.`)}\n              className=\"flex w-20 flex-col items-center gap-2 text-center\"\n            >\n              <span className=\"grid h-14 w-14 place-items-center rounded-xl bg-white text-blue-800\">\n                <Icon size={22} />\n              </span>\n              <span className=\"text-xs text-white/90\">{item.label}</span>\n            </button>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/Home.jsx": "// Home page: welcome band, account tiles, favourite links and a static Send Money card.\nimport { useState } from \"react\";\nimport { ChevronRight } from \"lucide-react\";\nimport PageHero from \"../components/banking/PageHero\";\nimport SendMoney from \"../components/banking/SendMoney\";\nimport QuickRecharge from \"../components/banking/QuickRecharge\";\nimport BillsRecharges from \"../components/banking/BillsRecharges\";\nimport { formatAmount } from \"../data/demoAccount\";\nimport { getCurrentBalance } from \"../data/demoTransactions\";\n\nexport default function Home({ user, setPage }) {\n  const [showBalance, setShowBalance] = useState(false);\n\n  // Fictional balance up to today (changes automatically as the date moves).\n  const now = new Date();\n  const balance = getCurrentBalance();\n\n  const favourites = [\n    { label: \"Account Statement\", onClick: () => setPage(\"statement\") },\n    { label: \"Open FD\" },\n    { label: \"Download FD Summary\" },\n    { label: \"Sweep-in / OD against FD\" },\n    { label: \"CASA Interest Certificate\" },\n  ];\n\n  return (\n    <div>\n      <PageHero title={`Welcome, ${user.name}`}>\n        <p className=\"mt-1 text-xs text-white/60\">Last logged in at {now.toLocaleString(\"en-IN\")}</p>\n        <div className=\"mt-6 flex flex-wrap gap-6 text-sm text-white/80\">\n          {[\"Accounts\", \"Cards\", \"FD/Flexi-RD\", \"Loans\", \"Invest\", \"Insure\"].map((t, i) => (\n            <span key={t} className={i === 0 ? \"border-b-2 border-white pb-1 text-white\" : \"\"}>{t}</span>\n          ))}\n        </div>\n      </PageHero>\n\n      <div className=\"mx-auto -mt-20 grid max-w-7xl gap-6 px-4 pb-10 sm:px-8 lg:grid-cols-[1fr_320px]\">\n        <div>\n          {/* Account tiles */}\n          <label className=\"mb-3 flex items-center gap-2 text-sm text-white\">\n            Show Balance\n            <input type=\"checkbox\" checked={showBalance} onChange={(e) => setShowBalance(e.target.checked)} />\n          </label>\n          <div className=\"grid gap-4 sm:grid-cols-3\">\n            <div className=\"rounded-2xl bg-violet-100 p-5 shadow-lg\">\n              <p className=\"text-sm font-semibold text-slate-700\">Savings Accounts</p>\n              <p className=\"mt-2 text-lg font-bold text-slate-800\">{showBalance ? formatAmount(balance) : \"XXXXXXXX\"}</p>\n              <button type=\"button\" onClick={() => setPage(\"statement\")} className=\"mt-8 w-full rounded-lg bg-blue-800 py-2.5 text-sm font-semibold text-white\">\n                Get Statement\n              </button>\n            </div>\n            <div className=\"rounded-2xl bg-indigo-700 p-5 text-white shadow-lg\">\n              <p className=\"text-sm\">Enjoy tax benefits and assured returns</p>\n              <button type=\"button\" className=\"mt-8 w-full rounded-lg bg-white py-2.5 text-sm font-semibold text-indigo-800\">Open PPF Account</button>\n            </div>\n            <div className=\"rounded-2xl bg-indigo-700 p-5 text-white shadow-lg\">\n              <p className=\"text-sm\">Open Demat &amp; Trading Acc in a few clicks</p>\n              <button type=\"button\" className=\"mt-8 w-full rounded-lg bg-white py-2.5 text-sm font-semibold text-indigo-800\">Open Demat Account</button>\n            </div>\n          </div>\n\n          <div className=\"mt-6\">\n            <SendMoney />\n          </div>\n\n          <div className=\"mt-6 grid gap-6 lg:grid-cols-2\">\n            <QuickRecharge />\n            <BillsRecharges />\n          </div>\n        </div>\n\n        {/* Favourite links */}\n        <aside className=\"h-fit rounded-2xl bg-white p-5 shadow-lg\">\n          <h2 className=\"mb-2 font-semibold text-slate-800\">My Favourite Links</h2>\n          <ul>\n            {favourites.map((f) => (\n              <li key={f.label}>\n                <button type=\"button\" onClick={f.onClick} className=\"flex w-full items-center justify-between py-3 text-left text-sm text-slate-700\">\n                  {f.label} <ChevronRight size={16} />\n                </button>\n              </li>\n            ))}\n          </ul>\n        </aside>\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/Accounts.jsx": "// Accounts page: savings account card, recent transactions list and quick links.\nimport { useState, useMemo } from \"react\";\nimport { Landmark, Receipt, FileText, Info } from \"lucide-react\";\nimport PageHero from \"../components/banking/PageHero\";\nimport QuickLinks from \"../components/banking/QuickLinks\";\nimport { ACCOUNT, formatAmount, formatDate } from \"../data/demoAccount\";\nimport { getMonthlyTransactions, getCurrentBalance } from \"../data/demoTransactions\";\n\nexport default function Accounts({ setPage }) {\n  const [showTx, setShowTx] = useState(false);\n\n  const { transactions, balance } = useMemo(() => {\n    // Last 20 transactions (previous month + this month, up to today), newest first.\n    const now = new Date();\n    const prev = new Date(now.getFullYear(), now.getMonth() - 1, 1);\n    const list = [\n      ...getMonthlyTransactions(prev.getMonth() + 1, prev.getFullYear()),\n      ...getMonthlyTransactions(now.getMonth() + 1, now.getFullYear()),\n    ];\n    return { transactions: list.slice(-20).reverse(), balance: getCurrentBalance() };\n  }, []);\n\n  const links = [\n    { label: \"Account Statement\", icon: FileText, onClick: () => setPage(\"statement\") },\n    { label: \"Open a Savings Account\", icon: Landmark },\n    { label: \"Open a Deposit\", icon: Landmark },\n    { label: \"View FD Interest Rates\", icon: Receipt },\n    { label: \"Manage e-Statements\", icon: FileText },\n  ];\n\n  return (\n    <div>\n      <PageHero title=\"Accounts\" />\n      <div className=\"mx-auto -mt-20 grid max-w-7xl gap-6 px-4 pb-10 sm:px-8 lg:grid-cols-[1fr_340px]\">\n        <div className=\"space-y-6\">\n          <div className=\"rounded-2xl bg-white p-6 shadow-lg\">\n            <div className=\"flex items-start justify-between\">\n              <div>\n                <h2 className=\"text-lg font-bold text-blue-900\">{ACCOUNT.type}</h2>\n                <p className=\"mt-0.5 text-xl font-bold tracking-wider text-slate-900\">{ACCOUNT.masked}</p>\n              </div>\n              <div className=\"text-right\">\n                <p className=\"text-2xl font-bold text-slate-800\">{formatAmount(balance)}</p>\n                <p className=\"text-xs text-slate-500\">Available Balance</p>\n              </div>\n            </div>\n            <div className=\"mt-4 flex justify-between border-t border-slate-100 pt-4 text-sm text-slate-600\">\n              <span>Account Balance</span><span className=\"font-semibold\">{formatAmount(balance)}</span>\n            </div>\n            <div className=\"mt-2 flex justify-between text-sm text-slate-600\">\n              <span>Total Overdraft</span><span className=\"font-semibold\">{formatAmount(0)}</span>\n            </div>\n            <div className=\"mt-5 flex justify-end gap-3\">\n              <button type=\"button\" className=\"rounded-lg border border-blue-800 px-5 py-2.5 text-sm font-semibold text-blue-800\">Account Details</button>\n              <button type=\"button\" onClick={() => setShowTx(!showTx)} className=\"rounded-lg bg-blue-800 px-5 py-2.5 text-sm font-semibold text-white\">\n                Recent Transaction\n              </button>\n            </div>\n          </div>\n\n          {showTx && (\n            <div className=\"overflow-hidden rounded-2xl bg-white shadow-lg\">\n              <p className=\"border-b border-slate-100 px-6 py-4 text-xs text-slate-500\">Showing up to last 20 transactions (demo data).</p>\n              <ul className=\"divide-y divide-slate-100\">\n                {transactions.map((t) => (\n                  <li key={t.id} className=\"flex items-center justify-between px-6 py-4 text-sm\">\n                    <div>\n                      <p className=\"font-semibold text-slate-800\">{t.description}</p>\n                      <p className=\"text-xs text-slate-400\">{formatDate(t.date)}</p>\n                    </div>\n                    <span className={`font-bold ${t.type === \"Credit\" ? \"text-green-600\" : \"text-red-600\"}`}>\n                      {t.type === \"Credit\" ? \"+\" : \"-\"}{formatAmount(t.amount)}\n                    </span>\n                  </li>\n                ))}\n              </ul>\n            </div>\n          )}\n\n          <div className=\"flex items-center gap-3 rounded-2xl bg-white p-5 text-sm text-slate-600 shadow-lg\">\n            <Info size={18} className=\"text-amber-600\" />\n            Educational demo only. Not an official bank website. All data is fictional.\n          </div>\n        </div>\n\n        <QuickLinks links={links} />\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/AccountStatement.jsx": "// Account Statement page: pick a period, \"prepare\" the statement (progress popup),\n// download a DEMO PDF, and see it listed under \"Recently Downloaded Statements\".\nimport { useState, useMemo, useEffect, useRef } from \"react\";\nimport jsPDF from \"jspdf\";\nimport * as XLSX from \"xlsx\";\nimport {\n  Download, Mail, ChevronDown, CalendarDays, X, CheckCircle2,\n  UserSquare, FileText, ScrollText, ShieldAlert, Info,\n} from \"lucide-react\";\nimport PageHero from \"../components/banking/PageHero\";\nimport QuickLinks from \"../components/banking/QuickLinks\";\nimport { ACCOUNT, formatAmount, formatDate, formatDMY } from \"../data/demoAccount\";\nimport { getMonthlyTransactions, calculateMonthlySummary, getBalanceBefore, getCurrentBalance } from \"../data/demoTransactions\";\n\nconst MONTHS = [\"January\",\"February\",\"March\",\"April\",\"May\",\"June\",\"July\",\"August\",\"September\",\"October\",\"November\",\"December\"];\n\n// ---------- Download formats ----------\n\n// Options shown in the format dropdown. `ext` is used for the downloaded file name.\nconst FORMATS = [\n  { value: \"pdf\", label: \"PDF\", ext: \"pdf\" },\n  { value: \"xlsx\", label: \"Excel\", ext: \"xlsx\" },\n  { value: \"csv\", label: \"CSV\", ext: \"csv\" },\n  { value: \"txt\", label: \"Text\", ext: \"txt\" },\n];\n\n// true  = PDF option gives your own PDF from the /public folder.\n// false = PDF option generates the demo PDF with jsPDF (old behaviour).\nconst USE_OWN_PDF = true;\n\n// File placed in latest/public/ (served at the site root).\nconst OWN_PDF_URL = `${import.meta.env.BASE_URL}demo-statement.pdf`;\n\n// Browser download of any Blob (used for CSV / Text).\nfunction saveBlob(blob, fileName) {\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url;\n  link.download = fileName;\n  document.body.appendChild(link);\n  link.click();\n  link.remove();\n  URL.revokeObjectURL(url);\n}\n\n// Browser download of your own PDF file above.\nfunction saveOwnPdf(fileName) {\n  const link = document.createElement(\"a\");\n  link.href = OWN_PDF_URL;\n  link.download = fileName;\n  document.body.appendChild(link);\n  link.click();\n  link.remove();\n}\n\n// Turn transactions into table rows with a running balance (used by Excel / CSV / Text).\n// `opening` = balance at the start of the selected period.\nfunction buildRows(transactions, opening) {\n  let balance = opening;\n  return transactions.map((t) => {\n    balance = Math.round((balance + (t.type === \"Credit\" ? t.amount : -t.amount)) * 100) / 100;\n    return {\n      Date: formatDMY(t.date),\n      Narration: t.narration || t.description,\n      \"Ref No.\": t.reference || \"\",\n      \"Debit (INR)\": t.type === \"Debit\" ? t.amount : \"\",\n      \"Credit (INR)\": t.type === \"Credit\" ? t.amount : \"\",\n      \"Balance (INR)\": balance,\n    };\n  });\n}\n\n// Excel file: sheet 1 = transactions, sheet 2 = demo info.\nfunction saveExcel(label, transactions, opening, fileName) {\n  const sheet = XLSX.utils.json_to_sheet(buildRows(transactions, opening));\n  sheet[\"!cols\"] = [{ wch: 12 }, { wch: 60 }, { wch: 20 }, { wch: 14 }, { wch: 14 }, { wch: 16 }];\n  const info = XLSX.utils.aoa_to_sheet([\n    [\"DEMO STATEMENT - FICTIONAL DATA\"],\n    [\"Account\", ACCOUNT.masked],\n    [\"Period\", label],\n    [\"Not issued by any bank. Not valid as financial proof.\"],\n  ]);\n  info[\"!cols\"] = [{ wch: 50 }, { wch: 24 }];\n  const book = XLSX.utils.book_new();\n  XLSX.utils.book_append_sheet(book, sheet, \"Statement\");\n  XLSX.utils.book_append_sheet(book, info, \"Info\");\n  XLSX.writeFile(book, fileName);\n}\n\n// CSV file (opens in Excel too).\nfunction saveCsv(transactions, opening, fileName) {\n  const csv = XLSX.utils.sheet_to_csv(XLSX.utils.json_to_sheet(buildRows(transactions, opening)));\n  saveBlob(new Blob([csv], { type: \"text/csv;charset=utf-8\" }), fileName);\n}\n\n// Plain text file with aligned columns.\nfunction saveText(label, transactions, opening, fileName) {\n  const rows = buildRows(transactions, opening);\n  const lines = [\n    \"DEMO STATEMENT - FICTIONAL DATA (NOT ISSUED BY ANY BANK)\",\n    `Account: ${ACCOUNT.masked}`,\n    `Period : ${label}`,\n    \"\",\n    [\"Date\".padEnd(12), \"Narration\".padEnd(54), \"Debit\".padStart(12), \"Credit\".padStart(12), \"Balance\".padStart(14)].join(\" \"),\n    ...rows.map((r) =>\n      [\n        r.Date.padEnd(12),\n        r.Narration.slice(0, 54).padEnd(54),\n        String(r[\"Debit (INR)\"]).padStart(12),\n        String(r[\"Credit (INR)\"]).padStart(12),\n        String(r[\"Balance (INR)\"]).padStart(14),\n      ].join(\" \")\n    ),\n  ];\n  saveBlob(new Blob([lines.join(\"\\n\")], { type: \"text/plain;charset=utf-8\" }), fileName);\n}\n\n// ---------- Period helpers ----------\n\n// Dropdown options: Recent, last 6 months (newest first), financial years, custom.\nfunction buildPeriodOptions() {\n  const now = new Date();\n  const opts = [{ value: \"recent\", label: \"Recent Transactions\" }];\n  for (let i = 0; i < 6; i++) {\n    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);\n    opts.push({ value: `m:${d.getFullYear()}-${d.getMonth()}`, label: `${MONTHS[d.getMonth()]} ${d.getFullYear()}` });\n  }\n  opts.push({ value: \"cfy\", label: \"Current Financial Year\" });\n  opts.push({ value: \"pfy\", label: \"Previous Financial Year\" });\n  opts.push({ value: \"custom\", label: \"Custom Date\" });\n  return opts;\n}\n\n// Turn a dropdown value into { from, to } dates. Financial year = 1 Apr to 31 Mar.\nfunction resolveRange(period, customFrom, customTo) {\n  const now = new Date();\n  const fyStart = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;\n  if (period === \"recent\") return { from: new Date(now.getFullYear(), now.getMonth(), 1), to: now };\n  if (period.startsWith(\"m:\")) {\n    const [y, m] = period.slice(2).split(\"-\").map(Number);\n    return { from: new Date(y, m, 1), to: new Date(y, m + 1, 0) };\n  }\n  if (period === \"cfy\") return { from: new Date(fyStart, 3, 1), to: now };\n  if (period === \"pfy\") return { from: new Date(fyStart - 1, 3, 1), to: new Date(fyStart, 2, 31) };\n  return { from: new Date(customFrom), to: new Date(customTo) };\n}\n\n// Collect demo transactions for every month between from and to, then filter by date.\nfunction getTransactionsInRange(from, to) {\n  const list = [];\n  const cursor = new Date(from.getFullYear(), from.getMonth(), 1);\n  while (cursor <= to) {\n    list.push(...getMonthlyTransactions(cursor.getMonth() + 1, cursor.getFullYear()));\n    cursor.setMonth(cursor.getMonth() + 1);\n  }\n  const end = new Date(to.getFullYear(), to.getMonth(), to.getDate(), 23, 59, 59);\n  return list.filter((t) => t.date >= from && t.date <= end).sort((a, b) => a.date - b.date);\n}\n\n// ---------- PDF (always marked as DEMO) ----------\n\nfunction buildPdf(label, transactions, opening) {\n  const summary = calculateMonthlySummary(transactions);\n  const closing = opening + summary.credit - summary.debit;\n  const pdf = new jsPDF(\"p\", \"mm\", \"a4\");\n  const W = pdf.internal.pageSize.getWidth();\n  const H = pdf.internal.pageSize.getHeight();\n  let y = 20;\n\n  function watermark() {\n    pdf.setTextColor(235, 225, 225);\n    pdf.setFontSize(25);\n    pdf.setFont(\"helvetica\", \"bold\");\n    pdf.text(\"DEMO - NOT A BANK STATEMENT\", W / 2, H / 2, { align: \"center\", angle: 35 });\n    pdf.setTextColor(35, 45, 60);\n  }\n\n  function header() {\n    pdf.setFillColor(7, 65, 125);\n    pdf.rect(0, 0, W, 39, \"F\");\n    pdf.setTextColor(255, 255, 255);\n    pdf.setFontSize(19);\n    pdf.setFont(\"helvetica\", \"bold\");\n    pdf.text(\"BLUEBANK DEMO\", 15, 17);\n    pdf.setFontSize(9);\n    pdf.setFont(\"helvetica\", \"normal\");\n    pdf.text(\"FICTIONAL DIGITAL BANKING EXPERIENCE\", 15, 25);\n    pdf.text(\"SAMPLE DOCUMENT\", W - 15, 17, { align: \"right\" });\n    pdf.setTextColor(35, 45, 60);\n    pdf.setFontSize(15);\n    pdf.setFont(\"helvetica\", \"bold\");\n    pdf.text(\"ACCOUNT STATEMENT\", 15, 53);\n    pdf.setFontSize(10);\n    pdf.setFont(\"helvetica\", \"normal\");\n    pdf.text(`Statement Period: ${label}`, 15, 61);\n    pdf.text(\"Account Holder: DEMO USER\", 15, 70);\n    pdf.text(`Account Number: ${ACCOUNT.masked}`, 15, 77);\n    y = 91;\n  }\n\n  function tableHeader() {\n    pdf.setFillColor(7, 65, 125);\n    pdf.rect(15, y, W - 30, 10, \"F\");\n    pdf.setTextColor(255, 255, 255);\n    pdf.setFontSize(8);\n    pdf.setFont(\"helvetica\", \"bold\");\n    pdf.text(\"DATE\", 18, y + 7);\n    pdf.text(\"DESCRIPTION\", 49, y + 7);\n    pdf.text(\"TYPE\", 113, y + 7);\n    pdf.text(\"AMOUNT (INR)\", 151, y + 7);\n    pdf.setTextColor(35, 45, 60);\n    y += 10;\n  }\n\n  watermark();\n  header();\n\n  pdf.setFillColor(240, 245, 251);\n  pdf.roundedRect(15, y, W - 30, 39, 3, 3, \"F\");\n  pdf.setFontSize(9);\n  pdf.setFont(\"helvetica\", \"normal\");\n  pdf.text(\"OPENING BALANCE\", 20, y + 10);\n  pdf.text(\"TOTAL CREDIT\", 82, y + 10);\n  pdf.text(\"TOTAL DEBIT\", 145, y + 10);\n  pdf.setFont(\"helvetica\", \"bold\");\n  pdf.setFontSize(11);\n  pdf.text(formatAmount(opening), 20, y + 23);\n  pdf.text(formatAmount(summary.credit), 82, y + 23);\n  pdf.text(formatAmount(summary.debit), 145, y + 23);\n  y += 50;\n  pdf.text(`CLOSING BALANCE: ${formatAmount(closing)}`, 15, y);\n  y += 13;\n  tableHeader();\n\n  transactions.forEach((t, i) => {\n    if (y > H - 27) {\n      pdf.setFontSize(8);\n      pdf.text(\"DEMO DOCUMENT - NOT VALID FOR BANKING PURPOSES\", 15, H - 12);\n      pdf.addPage();\n      watermark();\n      header();\n      tableHeader();\n    }\n    if (i % 2 === 0) {\n      pdf.setFillColor(244, 247, 250);\n      pdf.rect(15, y, W - 30, 10, \"F\");\n    }\n    pdf.setFont(\"helvetica\", \"normal\");\n    pdf.setFontSize(8);\n    pdf.text(formatDate(t.date), 18, y + 6.5);\n    pdf.text(t.description, 49, y + 6.5);\n    pdf.text(t.type.toUpperCase(), 113, y + 6.5);\n    pdf.setTextColor(t.type === \"Credit\" ? 20 : 190, t.type === \"Credit\" ? 135 : 55, t.type === \"Credit\" ? 75 : 55);\n    pdf.text(formatAmount(t.amount), W - 18, y + 6.5, { align: \"right\" });\n    pdf.setTextColor(35, 45, 60);\n    y += 10;\n  });\n\n  if (y > H - 27) {\n    pdf.addPage();\n    watermark();\n    header();\n    y = 110;\n  }\n  pdf.setDrawColor(210, 220, 230);\n  pdf.line(15, y + 5, W - 15, y + 5);\n  pdf.setFontSize(8);\n  pdf.setTextColor(110, 120, 130);\n  pdf.text(\"This document contains fictional data for software demonstration only.\", W / 2, y + 13, { align: \"center\" });\n  pdf.text(\"NOT ISSUED BY ANY BANK | NOT VALID AS FINANCIAL PROOF\", W / 2, y + 20, { align: \"center\" });\n  return pdf;\n}\n\n// ---------- Page ----------\n\nexport default function AccountStatement({ setPage }) {\n  const options = useMemo(() => buildPeriodOptions(), []);\n  const [period, setPeriod] = useState(\"pfy\");\n  const [format, setFormat] = useState(\"pdf\"); // selected download format\n  const [customFrom, setCustomFrom] = useState(\"\");\n  const [customTo, setCustomTo] = useState(\"\");\n  const [preparing, setPreparing] = useState(false);\n  const [progress, setProgress] = useState(0);\n  const [success, setSuccess] = useState(false);\n  const [recent, setRecent] = useState([]); // recently downloaded statements (this session)\n\n  const isCustom = period === \"custom\";\n  const range = resolveRange(period, customFrom, customTo);\n  const rangeValid = !isNaN(range.from) && !isNaN(range.to) && range.from <= range.to;\n  const label = rangeValid ? `${formatDMY(range.from)} to ${formatDMY(range.to)}` : \"\";\n\n  // Fictional available balance shown on the account row.\n  const available = getCurrentBalance();\n\n  // Fake \"Preparing your Statement...\" progress bar, then generate and save the PDF.\n  const timerRef = useRef(null);\n  useEffect(() => () => clearInterval(timerRef.current), []); // stop timer on unmount\n\n  // One place that decides which file the user gets, based on the chosen format.\n  function downloadForPeriod(snap) {\n    const fmt = FORMATS.find((f) => f.value === snap.format) || FORMATS[0];\n    const fileName = `Statement-${formatDMY(snap.from)}-to-${formatDMY(snap.to)}.${fmt.ext}`;\n    const transactions = getTransactionsInRange(snap.from, snap.to);\n    const opening = getBalanceBefore(snap.from); // balance at start of the period\n\n    if (fmt.value === \"pdf\") {\n      if (USE_OWN_PDF) saveOwnPdf(fileName);\n      else buildPdf(snap.label, transactions, opening).save(fileName);\n    } else if (fmt.value === \"xlsx\") {\n      saveExcel(snap.label, transactions, opening, fileName);\n    } else if (fmt.value === \"csv\") {\n      saveCsv(transactions, opening, fileName);\n    } else {\n      saveText(snap.label, transactions, opening, fileName);\n    }\n  }\n\n  function finishDownload(snap) {\n    downloadForPeriod(snap);\n    setRecent((list) => [snap, ...list]);\n    setPreparing(false);\n    setSuccess(true);\n  }\n\n  function startDownload() {\n    if (!rangeValid) {\n      alert(\"Please select a valid From and To date.\");\n      return;\n    }\n    // Snapshot the selected period so later dropdown changes don't affect this download.\n    const snap = { label, from: range.from, to: range.to, format };\n    let value = 0;\n    setSuccess(false);\n    setProgress(0);\n    setPreparing(true);\n    clearInterval(timerRef.current);\n    timerRef.current = setInterval(() => {\n      value += 10;\n      setProgress(value);\n      if (value >= 100) {\n        clearInterval(timerRef.current);\n        finishDownload(snap);\n      }\n    }, 200);\n  }\n\n  function cancelPreparing() {\n    clearInterval(timerRef.current);\n    setPreparing(false);\n  }\n\n  function redownload(item) {\n    downloadForPeriod(item);\n  }\n\n  const demoAlert = (what) => () => alert(`${what} is not available in this demo.`);\n\n  const links = [\n    { label: \"Go to Account Details\", icon: UserSquare, onClick: () => setPage(\"accounts\") },\n    { label: \"Forms Center\", icon: FileText, onClick: demoAlert(\"Forms Center\") },\n    { label: \"Download Interest Certificate\", icon: ScrollText, onClick: demoAlert(\"Interest certificate\") },\n    { label: \"Download Balance Certificate\", icon: ScrollText, onClick: demoAlert(\"Balance certificate\") },\n    { label: \"Raise Dispute and Report Fraud\", icon: ShieldAlert, onClick: demoAlert(\"Dispute\") },\n  ];\n\n  return (\n    <div>\n      <PageHero title=\"Account Statement\" onBack={() => setPage(\"accounts\")} />\n\n      <div className=\"mx-auto -mt-20 grid max-w-7xl gap-6 px-4 pb-10 sm:px-8 lg:grid-cols-[1fr_340px]\">\n        <div className=\"space-y-6\">\n          {/* Success banner */}\n          {success && (\n            <div className=\"flex items-start justify-between rounded-lg border border-green-300 bg-green-50 p-4\">\n              <div className=\"flex gap-3\">\n                <CheckCircle2 className=\"mt-0.5 text-green-600\" size={18} />\n                <div>\n                  <p className=\"text-sm font-semibold text-slate-800\">Download Successful</p>\n                  <p className=\"text-xs text-slate-600\">Statement downloaded successfully.</p>\n                </div>\n              </div>\n              <button type=\"button\" onClick={() => setSuccess(false)} aria-label=\"Close\"><X size={18} /></button>\n            </div>\n          )}\n\n          {/* Select account and period */}\n          <div className=\"rounded-2xl bg-white p-6 shadow-lg\">\n            <h2 className=\"mb-5 font-semibold text-slate-800\">Select Account and Statement Period</h2>\n\n            <div className=\"flex items-center justify-between rounded-xl border border-slate-200 p-4\">\n              <div>\n                <p className=\"text-base font-bold text-slate-800\">{ACCOUNT.type}</p>\n                <p className=\"mt-0.5 text-lg font-bold tracking-wider text-slate-900\">{ACCOUNT.masked}</p>\n              </div>\n              <div className=\"flex items-center gap-4\">\n                <div className=\"text-right\">\n                  <p className=\"font-bold text-slate-800\">{formatAmount(available)}</p>\n                  <p className=\"text-[11px] text-slate-500\">Available Balance</p>\n                </div>\n                <ChevronDown size={18} />\n              </div>\n            </div>\n\n            <div className=\"mt-4 grid gap-3 sm:grid-cols-3\">\n              <select\n                value={period}\n                onChange={(e) => setPeriod(e.target.value)}\n                className=\"rounded-lg border-2 border-blue-700 bg-white p-3 text-sm outline-none\"\n              >\n                {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}\n              </select>\n\n              <DateBox disabled={!isCustom} label=\"From Date\" value={isCustom ? customFrom : rangeValid ? toInput(range.from) : \"\"} onChange={setCustomFrom} />\n              <DateBox disabled={!isCustom} label=\"To Date\" value={isCustom ? customTo : rangeValid ? toInput(range.to) : \"\"} onChange={setCustomTo} />\n            </div>\n\n            <div className=\"mt-4 flex flex-wrap items-center gap-3 rounded-lg bg-slate-100 p-3\">\n              <p className=\"w-40 text-xs text-slate-500\">Download / Email statement for selected period</p>\n              <select\n                value={format}\n                onChange={(e) => setFormat(e.target.value)}\n                className=\"rounded-lg border border-slate-300 bg-white p-3 text-sm\"\n              >\n                {FORMATS.map((f) => <option key={f.value} value={f.value}>{f.label}</option>)}\n              </select>\n              <button type=\"button\" onClick={startDownload} className=\"flex items-center gap-2 rounded-lg bg-blue-800 px-6 py-3 text-sm font-semibold text-white hover:bg-blue-900\">\n                <Download size={16} /> Download\n              </button>\n              <button type=\"button\" onClick={demoAlert(\"Email\")} className=\"flex items-center gap-2 rounded-lg border border-blue-800 bg-white px-6 py-3 text-sm font-semibold text-blue-800\">\n                <Mail size={16} /> Email (PDF)\n              </button>\n            </div>\n\n            <p className=\"mt-6 text-xs font-semibold text-slate-600\">Note:</p>\n            <ul className=\"mt-1 list-disc pl-5 text-xs text-slate-600\">\n              <li>This is a demo project. The statement data is for demonstration only.</li>\n            </ul>\n          </div>\n\n          {/* Recently downloaded */}\n          <div className=\"rounded-2xl bg-white p-6 shadow-lg\">\n            <h2 className=\"font-semibold text-slate-800\">Recently Downloaded Statements</h2>\n            <p className=\"mt-1 text-xs text-slate-500\">Statements downloaded in this session are listed here.</p>\n            <div className=\"mt-4 overflow-x-auto\">\n              <table className=\"w-full min-w-[480px] text-left text-sm\">\n                <thead className=\"bg-slate-100 text-xs text-slate-500\">\n                  <tr><th className=\"p-3\">Statement Period</th><th className=\"p-3\">Format</th><th className=\"p-3\">Status</th></tr>\n                </thead>\n                <tbody>\n                  {recent.length === 0 && (\n                    <tr><td colSpan={3} className=\"p-4 text-xs text-slate-400\">No statements downloaded yet.</td></tr>\n                  )}\n                  {recent.map((item, i) => (\n                    <tr key={i} className=\"border-t border-slate-100\">\n                      <td className=\"p-3\">{item.label}</td>\n                      <td className=\"p-3\">{(FORMATS.find((f) => f.value === item.format) || FORMATS[0]).label}</td>\n                      <td className=\"p-3\">\n                        <button type=\"button\" onClick={() => redownload(item)} className=\"flex items-center gap-2 rounded-lg bg-blue-800 px-4 py-2 text-xs font-semibold text-white\">\n                          <Download size={14} /> Download\n                        </button>\n                      </td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div className=\"flex items-center gap-3 rounded-2xl bg-slate-100 p-4 text-sm text-slate-600\">\n            <Info size={18} className=\"text-amber-600\" />\n            Educational demo only. Not an official bank website. All data is fictional.\n          </div>\n        </div>\n\n        <QuickLinks links={links} />\n      </div>\n\n      {/* Preparing popup */}\n      {preparing && (\n        <div className=\"fixed inset-0 z-50 grid place-items-center bg-slate-900/50 p-4\">\n          <div className=\"w-full max-w-md rounded-2xl bg-white p-6 shadow-xl\">\n            <div className=\"flex items-start justify-between\">\n              <h3 className=\"text-lg font-semibold text-slate-800\">Preparing your Statement...</h3>\n              <button type=\"button\" onClick={cancelPreparing} aria-label=\"Close\"><X size={18} /></button>\n            </div>\n            <div className=\"mt-5 h-2 rounded-full bg-slate-200\">\n              <div className=\"h-2 rounded-full bg-blue-700 transition-all\" style={{ width: `${progress}%` }} />\n            </div>\n            <p className=\"mt-4 text-sm text-slate-600\">It might take a few seconds</p>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\n// yyyy-mm-dd string for <input type=\"date\">\nfunction toInput(d) {\n  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, \"0\")}-${String(d.getDate()).padStart(2, \"0\")}`;\n}\n\n// Date field: greyed out unless \"Custom Date\" is selected.\nfunction DateBox({ label, value, onChange, disabled }) {\n  return (\n    <div className={`flex items-center gap-2 rounded-lg border p-3 ${disabled ? \"border-slate-200 bg-slate-100\" : \"border-slate-300 bg-white\"}`}>\n      <CalendarDays size={16} className=\"text-slate-500\" />\n      <input\n        type=\"date\"\n        aria-label={label}\n        value={value}\n        disabled={disabled}\n        onChange={(e) => onChange(e.target.value)}\n        className=\"w-full bg-transparent text-sm outline-none\"\n      />\n    </div>\n  );\n}\n",
};

for (const [relPath, content] of Object.entries(files)) {
  const full = path.join(process.cwd(), relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, "utf-8");
  console.log("written:", relPath);
}
console.log("\nDone. Restart your dev server: npm run dev");
